import {ToolRegistry} from './registry.js';
import type {ToolDefinitionSource} from './registry.js';

const weatherSchema = {
  type: 'object',
  properties: {location: {type: 'string'}},
  required: ['location'],
};

function weatherDefinition(inputSchema: Record<string, unknown>) {
  return {name: 'get_weather', description: 'Get weather for a location', inputSchema};
}

// One recording executor for every case: the delivered inputs plus the returned result carry the whole assertion.
function registerRecordingWeatherTool(
  registry: ToolRegistry,
  source: ToolDefinitionSource
): Array<Record<string, unknown>> {
  const deliveredInputs: Array<Record<string, unknown>> = [];
  registry.register(source, async input => {
    deliveredInputs.push(input);
    return 'sunny';
  });
  return deliveredInputs;
}

describe('ToolRegistry input validation', () => {
  it('names the missing required property in a rejection ToolResponse and never calls the executor', async () => {
    const registry = new ToolRegistry();
    const deliveredInputs = registerRecordingWeatherTool(registry, weatherDefinition(weatherSchema));

    const response = await registry.execute('get_weather', {});

    expect({deliveredInputs, rejection: response.result}).toEqual({
      deliveredInputs: [],
      rejection: expect.stringMatching(/location.*required/i),
    });
  });

  it('rejects a number where location must be a string, naming the field and expected type without the value', async () => {
    const registry = new ToolRegistry();
    const deliveredInputs = registerRecordingWeatherTool(registry, weatherDefinition(weatherSchema));

    const response = await registry.execute('get_weather', {location: 42});

    expect({
      deliveredInputs,
      namesField: response.result.includes('location'),
      namesExpectedType: response.result.includes('string'),
      echoesValue: response.result.includes('42'),
    }).toEqual({
      deliveredInputs: [],
      namesField: true,
      namesExpectedType: true,
      echoesValue: false,
    });
  });

  it('passes valid input with an undeclared extra property to the executor unchanged and exactly once', async () => {
    const registry = new ToolRegistry();
    const deliveredInputs = registerRecordingWeatherTool(registry, weatherDefinition(weatherSchema));

    const response = await registry.execute('get_weather', {location: 'Paris', unit: 'metric'});

    expect({deliveredInputs, response}).toEqual({
      deliveredInputs: [{location: 'Paris', unit: 'metric'}],
      response: {result: 'sunny'},
    });
  });

  it('throws Unknown tool for a name that was never registered', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('get_weather', {})).rejects.toThrow('Unknown tool: get_weather');
  });

  it('keeps validating against the schema compiled at register time across ten execute calls', async () => {
    const registry = new ToolRegistry();
    const inputSchema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const deliveredInputs = registerRecordingWeatherTool(registry, weatherDefinition(inputSchema));

    // Compiled from this schema at register: re-reading it now would change what execute enforces.
    inputSchema.required = ['ghost'];

    const results = [];
    for (let call = 0; call < 10; call += 1) {
      results.push((await registry.execute('get_weather', {location: 'Paris'})).result);
    }

    expect({deliveredInputs, results}).toEqual({
      deliveredInputs: Array.from({length: 10}, () => ({location: 'Paris'})),
      results: Array.from({length: 10}, () => 'sunny'),
    });
  });

  it('validates a function-valued definition source against the schema current at each call', async () => {
    const registry = new ToolRegistry();
    const schemasPerResolution = [
      weatherSchema,
      {
        type: 'object',
        properties: {region: {type: 'string'}},
        required: ['region'],
      },
    ];
    let resolutions = 0;
    const deliveredInputs = registerRecordingWeatherTool(registry, () =>
      weatherDefinition(schemasPerResolution[Math.min(resolutions++, schemasPerResolution.length - 1)])
    );

    const accepted = await registry.execute('get_weather', {region: 'eu-west'});
    const rejected = await registry.execute('get_weather', {location: 'Paris'});

    expect({
      deliveredInputs,
      acceptedResult: accepted.result,
      namesCurrentRequirement: rejected.result.includes('region') && /required/i.test(rejected.result),
      namesStaleRequirement: rejected.result.includes('location'),
    }).toEqual({
      deliveredInputs: [{region: 'eu-west'}],
      acceptedResult: 'sunny',
      namesCurrentRequirement: true,
      namesStaleRequirement: false,
    });
  });
});

# HAL Engine

A generic AI chat server framework with pluggable providers, tools, and transport.

HAL Engine extracts the core patterns of building an AI-powered chat backend into a reusable library. It handles streaming responses, tool execution loops, WebSocket connections, and session management -- you bring your own AI provider, auth, and domain tools.

## Features

- **Multi-provider support**: AWS Bedrock and Google Vertex AI implemented, OpenAI and Anthropic stubbed, plus a built-in Mock. Scored per method in [Providers](#providers) — a provider can implement one of `AIProvider`'s two methods without the other
- **Tool system**: Register custom tools with a JSON Schema `inputSchema`, executed in parallel within a configurable tool loop. The schema is forwarded to the model to shape the call it produces; it is **not** enforced before your executor runs, so validate the input you are handed
- **Streaming**: Real-time WebSocket streaming with thinking tag parsing and entry-based protocol
- **Pluggable auth**: Bring your own WebSocket and HTTP authentication
- **Pluggable session store**: In-memory default, swap in Redis/database/etc.
- **Configurable prompts**: Identity, domain context, response guidelines -- all injectable
- **Express + WebSocket**: Full HTTP API and WebSocket server out of the box

## Install

```bash
npm install @re-cinq/hal-engine
```

That is the supported install path, and the one this project releases against: every published version is built by a workflow run in this repository's CI and carries an npm provenance attestation. `npm audit signatures` verifies it, which tells you the tarball was built by a workflow of this repository from the commit the attestation names, rather than uploaded by whoever held a token. `0.2.0` was published once with a token, because the registry cannot hold a trusted publisher for a name that has never been published; every version after it is published by the release workflow from a published GitHub release, with no credential stored anywhere, and reaches you only after a maintainer approves it.

A git specifier also resolves, and four things differ. It builds `dist/` from a checkout through the `prepare` script rather than installing a built artefact, so your install runs this package's TypeScript compiler. It carries no provenance, because provenance is produced at publish time. It pins whatever commit your lockfile recorded, not a version, so `npm outdated` has nothing to compare and a fix reaches you only when you repoint it. And npm installs a dependency under its **key**, not the package's `name`.

That last one has a trap in it. An existing `"hal-engine": "github:…"` entry keeps resolving after the rename — the directory is still `node_modules/hal-engine`, so `import 'hal-engine'` keeps working while the package inside it declares `@re-cinq/hal-engine`. The rename produces no error, no warning and no failed build. Worse, following the rename and switching your imports to `@re-cinq/hal-engine` is what breaks: that specifier resolves to nothing until the key is renamed too. Move to the registry specifier, or rename the key and the imports together.

