import Ajv from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

// Only the members a rejection message reads; ajv's own error typing moved between the majors this range resolves against.
interface SchemaError {
  keyword?: unknown;
  instancePath?: unknown;
  dataPath?: unknown;
  message?: unknown;
  params?: {missingProperty?: unknown};
}

interface CompiledValidator {
  (input: unknown): boolean;
  errors?: SchemaError[] | null;
}

interface SchemaCompiler {
  compile(schema: Record<string, unknown>): CompiledValidator;
}

// ajv's Options and default export differ between those majors too, so the compiler is taken through a local contract.
const ajv = new (Ajv as unknown as new (options?: Record<string, unknown>) => SchemaCompiler)({
  strict: false,
  validateFormats: false,
});

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: CompiledValidator;
  validators: WeakMap<object, CompiledValidator>;
}

// ajv 8 points at the failing property with a JSON Pointer; the older majors this range can resolve against use dataPath.
function failingPath(error: SchemaError): string {
  if (typeof error.instancePath === 'string') return error.instancePath;
  return typeof error.dataPath === 'string' ? error.dataPath : '';
}

// A rejection describes the failing path and constraint only: tool input is where identifying data enters the engine.
function describeValidationErrors(errors: SchemaError[]): string {
  return errors
    .map(error => {
      const missingProperty = error.params?.missingProperty;
      if (error.keyword === 'required' && typeof missingProperty === 'string') {
        return `${failingPath(error)}/${missingProperty} is required`;
      }
      const at = failingPath(error) || 'input';
      return `${at} ${typeof error.message === 'string' ? error.message : 'failed validation'}`;
    })
    .join('; ');
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private compileValidator(toolName: string, schema: Record<string, unknown>): CompiledValidator {
    try {
      return ajv.compile(schema);
    } catch (error) {
      const reason = error instanceof Error ? error.message : String(error);
      throw new Error(`Tool ${toolName} has an invalid inputSchema: ${reason}`, {cause: error});
    }
  }

  private validatorFor(tool: StoredTool, definition: ToolDefinition): CompiledValidator {
    if (tool.validator) return tool.validator;
    const cached = tool.validators.get(definition.inputSchema);
    if (cached) return cached;
    const compiled = this.compileValidator(definition.name, definition.inputSchema);
    tool.validators.set(definition.inputSchema, compiled);
    return compiled;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const tool: StoredTool = {definitionSource: definition, execute, validators: new WeakMap()};
    // A static schema compiles here, so a broken one fails at startup rather than mid-conversation.
    if (typeof definition !== 'function') {
      tool.validator = this.compileValidator(resolved.name, resolved.inputSchema);
    }
    this.tools.set(resolved.name, tool);
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against the tool's inputSchema and returns a rejection ToolResponse rather than throwing (throws only for an unknown tool) — see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = this.validatorFor(tool, definition);
    if (!validate(input)) {
      const rejection = `Invalid input for tool ${name}: ${describeValidationErrors(validate.errors ?? [])}`;
      log.warn('tool', 'input rejected by inputSchema', {name, failures: rejection});
      return {result: rejection};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

